SELECT AVG(post_count) AS average_posts
FROM (
  SELECT COUNT(v.PostId) AS post_count
  FROM votes v
  INNER JOIN users u ON v.UserId = u.Id
  WHERE u.Age = (
    SELECT MAX(Age) FROM users
  )
  GROUP BY v.UserId
) AS oldest_users;

