    SELECT event_id FROM attendance WHERE link_to_member IN (
        SELECT link_to_member FROM attendance WHERE link_to_event IN (
            SELECT event_id FROM attendance WHERE link_to_member IN (
                SELECT link_to_member FROM attendance WHERE link_to_member IS NOT NULL
